  ('w_m_full_b', 'c_marko', 'Celo telo B', '[{"exerciseId":"m_deadlift","sets":3,"repsMin":5,"repsMax":5,"rir":3,"restSeconds":150},{"exerciseId":"m_ohp","sets":3,"repsMin":8,"repsMax":8,"rir":2,"restSeconds":120},{"exerciseId":"m_lat","sets":3,"repsMin":10,"repsMax":12,"rir":2,"restSeconds":90}]'::jsonb, 'Još jedan. Sledeći put dodaj 2,5 kg na čučanj.', 'public', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=900&q=75&auto=format&fit=crop', 'Mrtvo dizanje je glavno. Leđa ravna, sve ostalo je bonus.'),
